"""Minimum Cost to Cut a Stick — interval DP over the sorted cut positions.

With sentinels 0 and n added, dp[i][j] is the cheapest way to make every cut
strictly between positions i and j; the cost of the first cut there is always
the whole segment length.

Time: O(m^3)   Space: O(m^2)
"""
from functools import lru_cache
from typing import List


class Solution:
    def minCost(self, n: int, cuts: List[int]) -> int:
        points = sorted([0] + cuts + [n])

        @lru_cache(maxsize=None)
        def solve(i: int, j: int) -> int:
            if j - i < 2:
                return 0
            return min(points[j] - points[i] + solve(i, mid) + solve(mid, j)
                       for mid in range(i + 1, j))

        return solve(0, len(points) - 1)
